package com.tutorhub.tutor.controller;
import com.tutorhub.common.pagination.PageResponse;import com.tutorhub.common.security.CurrentUser;import com.tutorhub.tutor.dto.*;import com.tutorhub.tutor.service.TutorService;import jakarta.validation.Valid;import java.math.BigDecimal;import java.util.List;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;
@RestController @RequestMapping("/api/v1/tutors") public class TutorController {
 private final TutorService s;private final CurrentUser c;public TutorController(TutorService s,CurrentUser c){this.s=s;this.c=c;}
 @GetMapping PageResponse<TutorCardResponse> search(@RequestParam(required=false)Integer subjectId,@RequestParam(required=false)Short grade,@RequestParam(required=false)Integer districtId,@RequestParam(required=false)String mode,@RequestParam(required=false)Long minRate,@RequestParam(required=false)Long maxRate,@RequestParam(required=false)BigDecimal minRating,@RequestParam(required=false)String q,@RequestParam(defaultValue="newest")String sort,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return s.search(subjectId,grade,districtId,mode,minRate,maxRate,minRating,q,sort,Math.max(0,page),Math.clamp(size,1,100));}
 @GetMapping("/{id}") TutorPublicResponse one(@PathVariable long id){return s.publicProfile(id);}
 @GetMapping("/{id}/availability") List<AvailabilitySlotResponse> publicAvailability(@PathVariable long id,@RequestParam java.time.LocalDate date){return s.publicAvailability(id,date);}
 @GetMapping("/{id}/reviews") PageResponse<TutorReviewResponse> reviews(@PathVariable long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return s.reviews(id,Math.max(0,page),Math.clamp(size,1,100));}
 @GetMapping("/me") TutorProfileResponse me(){return s.me(c.require());}@PutMapping("/me") TutorProfileResponse update(@Valid@RequestBody TutorProfileRequest r){return s.update(c.require(),r);}
 @GetMapping("/me/subjects") List<TutorSubjectResponse> subjects(){return s.subjects(c.require());}@PutMapping("/me/subjects") List<TutorSubjectResponse> subjects(@Valid@RequestBody List<@Valid TutorSubjectRequest> r){return s.subjects(c.require(),r);}
 @GetMapping("/me/availability") List<AvailabilitySlotResponse> availability(){return s.availability(c.require());}@PutMapping("/me/availability") List<AvailabilitySlotResponse> availability(@Valid@RequestBody List<@Valid AvailabilitySlotRequest> r){return s.availability(c.require(),r);}
 @GetMapping("/me/documents") List<TutorDocumentResponse> docs(){return s.documents(c.require());}@PostMapping("/me/documents")@ResponseStatus(HttpStatus.CREATED) TutorDocumentResponse upload(@RequestParam String type,@RequestPart("file") MultipartFile f){return s.upload(c.require(),type,f);}@DeleteMapping("/me/documents/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void delete(@PathVariable long id){s.deleteDocument(c.require(),id);}
 @PostMapping("/me/submit")@ResponseStatus(HttpStatus.NO_CONTENT)void submit(){s.submit(c.require());}
}
